import itertools
import json
import sys

def solve():
    # Houses numbered left to right
    houses = [1, 2]

    # Attributes (domains)
    Names = ["Arnold", "Eric"]
    BookGenres = ["science fiction", "mystery"]
    Vacations = ["mountain", "beach"]
    Animals = ["cat", "horse"]
    MusicGenres = ["rock", "pop"]

    # Try all permutations respecting uniqueness
    for names_p in itertools.permutations(Names):
        for books_p in itertools.permutations(BookGenres):
            # Clue 5: The person who loves mystery books is in the first house.
            if books_p[0] != "mystery":
                continue

            for vacations_p in itertools.permutations(Vacations):
                # Clue 1: The person who loves beach vacations is Eric.
                idx_beach = vacations_p.index("beach")
                if names_p[idx_beach] != "Eric":
                    continue

                for music_p in itertools.permutations(MusicGenres):
                    # Clue 2: Pop music lover is the beach vacations lover.
                    if music_p.index("pop") != vacations_p.index("beach"):
                        continue

                    # Clue 3: Rock music lover is the mystery books lover.
                    if music_p.index("rock") != books_p.index("mystery"):
                        continue

                    for animals_p in itertools.permutations(Animals):
                        # Clue 4: The cat lover is not in the second house.
                        if animals_p[1] == "cat":
                            continue

                        # All constraints satisfied; construct solution
                        rows = []
                        for i in range(len(houses)):
                            rows.append([
                                str(houses[i]),
                                names_p[i],
                                books_p[i],
                                vacations_p[i],
                                animals_p[i],
                                music_p[i],
                            ])

                        result = {
                            "solution": {
                                "header": ["House", "Name", "BookGenre", "Vacation", "Animal", "MusicGenre"],
                                "rows": rows
                            }
                        }
                        print(json.dumps(result, ensure_ascii=False))
                        return

    # If no solution found (should not happen), output empty structure to keep valid JSON
    result = {
        "solution": {
            "header": ["House", "Name", "BookGenre", "Vacation", "Animal", "MusicGenre"],
            "rows": []
        }
    }
    print(json.dumps(result, ensure_ascii=False))

if __name__ == "__main__":
    solve()
